-- LA-1396 (spec LA-1394). The General Requirements tab of Kulka's estimate
-- C-00379, 117 N. Long Beach Rd, as a rate card beside gc_staffing_rates and
-- gc_field_office_rates (docs/precon/kulka-gc-rate-card.md). Source file:
-- `117 N Long Beach Rd GC's REV1.xlsx`, tab `General Requirements (GC- CM)`.
--
-- Every row comes from one job, a 120,000 SF warehouse, and says so in its own
-- columns so nobody reads a rate as a multifamily benchmark.
--
-- Group headings that carry no unit, rate, note or owner flag (for example
-- "Mounting" or "Dumpsters") are not rows. Their names lead the item name of
-- the lines beneath them. Every other numbered line on the tab is a row, with
-- or without a rate. source_row is the row on the tab.
--
-- Insurances & Bonds loads and is marked not priceable. Fee and insurance are
-- already markups, so pricing them here would count them twice. It stays that
-- way until Matt answers LA-1394 question 3.
--
-- The existing staffing and field-office tables are untouched.
create table gr_rates (
  id uuid primary key default gen_random_uuid(),
  section text not null,
  item text not null,
  -- How the source counts the rate: a week or month of a schedule phase, a
  -- unit named in `unit`, or a lump sum. not_stated is a line with no unit.
  basis text not null check (
    basis in ('phase_weeks', 'phase_months', 'unit', 'lump_sum', 'not_stated')
  ),
  unit text,
  -- construction where the source priced against the construction duration
  -- (65.14 weeks or 14.99 months). Null everywhere else, including phase
  -- bases the source priced against some other duration.
  phase text check (phase = 'construction'),
  -- Null where the source line carries no rate ("Included", "w/ Carpentry",
  -- or blank).
  rate numeric check (rate >= 0),
  -- The quantity the source used on this one job. Context only.
  job_quantity numeric,
  note text,
  -- The tab marks some lines Y under its Owner or Trades column.
  flagged_for text check (flagged_for in ('Owner', 'Trades')),
  priceable boolean not null default true,
  not_priceable_reason text,
  source_estimate text not null default 'C-00379',
  source_job text not null default '117 N. Long Beach Rd, one 120,000 SF warehouse',
  single_job_warehouse boolean not null default true check (single_job_warehouse),
  source_row integer not null unique,
  source_line integer not null unique,
  created_at timestamptz not null default now(),
  check (priceable or not_priceable_reason is not null),
  check (section <> 'Insurances & Bonds' or not priceable)
);


alter table gr_rates enable row level security;
